add('GET','/api/tests/:id/analytics',T,async({u,p})=>{const t=await one('SELECT * FROM tests WHERE id=?',p.id);if(!t||!canSee(u,t))throw E(404,'Test not found.');const Q=JSON.parse(t.questions),A=await q("SELECT answers FROM attempts WHERE test_id=? AND status='done'",p.id);return Q.map((item,i)=>{let correct=0,wrong={};for(const row of A){const ans=JSON.parse(row.answers||'[]')[i],score=mark([item],[ans]).got;correct+=score;if(item.type==='mc'&&ans!==item.ans&&ans!=null&&ans!=='')wrong[String(ans)]=(wrong[String(ans)]||0)+1}const top=Object.entries(wrong).sort((a,b)=>b[1]-a[1])[0];return{number:i+1,bloom:item.sec||'Unclassified',question:item.text||item.question||item.sec||'Question '+(i+1),type:item.type,marks:item.marks,attempts:A.length,correct_marks:correct,percent:A.length?Math.round(correct/(A.length*item.marks)*100):null,most_chosen_wrong:top?{answer:top[0],count:top[1]}:null}})});
