const safeSourceUrl=v=>{if(!v)return '';try{const u=new URL(String(v));if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw new Error();return u.toString()}catch{throw E(400,'Source URL must be a valid HTTP or HTTPS link.')}};const curriculumPhase=level=>{const n=Number(String(level||'').match(/[1-6]/)?.[0]||0);return n>=1&&n<=3?'P.1–P.3 · Thematic learning areas (NCDC)':n===4?'P.4 · Post-thematic transition (school grouping)':n>=5?'P.5–P.6 · Upper primary (school grouping)':'Not assigned'};const aiDailyLimit=()=>{const n=Number(process.env.AI_DAILY_LIMIT||30);return Number.isInteger(n)&&n>0?Math.min(200,n):30};const storyRow=s=>({...s,events:s.events?JSON.parse(s.events):[],characters:s.characters?JSON.parse(s.characters):[],tags:s.tags?JSON.parse(s.tags):[],curriculum_phase:curriculumPhase(s.level)});
